import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"故障检测器","description":"","frontmatter":{"title":"故障检测器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/failure-detectors.md","filePath":"cs/failure-detectors.md","lastUpdated":1789023840000}'),p={name:"cs/failure-detectors.md"};function m(u,a,_,f,E,D){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="故障检测器" tabindex="-1">故障检测器 <a class="header-anchor" href="#故障检测器" aria-label="Permalink to &quot;故障检测器&quot;">​</a></h1><div class="epigraph"><p>异步里不能可靠地知道谁死了。把「怀疑」做成预言机：完备与准确分档，共识的最小档是 $\\Diamond\\mathcal{P}$。</p><footer>—— 据 Chandra and Toueg, Unreliable Failure Detectors for Reliable Distributed Systems, JACM 1996；Chandra, Hadzilacos and Toueg, 1996 整理</footer></div><p>上一课<a href="/cs/chandy-lamport">快照</a>能切一致状态，切不出「这个进程还会不会再发消息」。上一课之前的<a href="/cs/sync-async-model">异步模型</a>里，超时不是原语。缺口是<strong>把怀疑从协议里抽出来</strong>：检测器输出「我怀疑 \\(p\\)」，协议只读这张名单。本课不重做崩溃定义。后课租约是检测器在实现里的一种带期限的形式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃停进程终将停止发消息；异步调度可以让活进程任意久不出现。任何基于超时的本地判断都可能错。Chandra–Toueg 不消除错误，而是给检测器<strong>性质</strong>：</p><ul><li>完备（completeness）：真故障终被所有正确进程怀疑。</li><li>准确（accuracy）：永不（或最终永不、或至少有一个正确进程永不）误伤正确进程。</li></ul><p>最强 \\(\\mathcal{P}\\)（Perfect）：强完备 + 强准确。最常用 \\(\\Diamond\\mathcal{P}\\)（eventually perfect）：终有一时刻之后，怀疑名单恰好是故障集。\\(\\Diamond\\mathcal{S}\\) 更弱，却已够异步崩溃共识（配多数派）。</p><p><span class="marginnote">CHT 1996 证明 \\(\\Diamond\\mathcal{S}\\) 是无初始值共识的最弱检测器。本课记结论，不搬归约证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上几乎都是心跳 + 自适应超时（φ accrual 等）：部分同步下终将成为 \\(\\Diamond\\mathcal{P}\\)。算法分层：共识模块只调用 <code>suspect(p)</code>，不内嵌 RTT。这样同一套 Paxos 可以换检测器实现。</p>',10)),(e(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HB%5B%22%E5%BF%83%E8%B7%B3%22%5D%20--%3E%20FD%5B%22%E6%A3%80%E6%B5%8B%E5%99%A8%22%5D%0A%20%20FD%20--%3E%20SUS%5B%22%E6%80%80%E7%96%91%E5%90%8D%E5%8D%95%22%5D%0A%20%20SUS%20--%3E%20CONS%5B%22%E5%85%B1%E8%AF%86%20%2F%20%E9%80%89%E4%B8%BE%20%E5%90%8E%E8%AF%BE%22%5D%0A%20%20SYNC%5B%22%E9%83%A8%E5%88%86%E5%90%8C%E6%AD%A5%22%5D%20-.-%3E%20FD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>错误怀疑的代价：把活领导者踢掉，活性抖动，安全性仍应成立——这把<a href="/cs/sync-async-model">时间模型</a>里「安全异步、活靠同步」说成了接口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强准确在真实网络几乎得不到：偶发长延迟就会误杀。所以工程检测器是 \\(\\Diamond\\) 类。心跳间隔与超时是运维旋钮，不是规格：调小则快但误伤多，调大则故障切换慢。租约下一课把「准确直到到期」做成短时的强准确窗口。</p><p>漏发故障下，检测器看到的是「不说话」，与崩溃不可分。拜占庭下「心跳还在」不表示协议被遵守，检测器抽象要另做——后课 PBFT 用法定人数与视图更换，不是 Chandra–Toueg 原版。</p><p>本课不把 Kubernetes liveness probe 当 \\(\\mathcal{P}\\)：探针失败只是本地重启策略，没有分布式完备性证明。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证最弱检测器，不写 φ 的公式。不把监控告警当成检测器输出。后课默认：异步共识读 \\(\\Diamond\\mathcal{S}\\) 或更强；实现用心跳逼近 \\(\\Diamond\\mathcal{P}\\)；误怀疑只许破坏活性。快照不是检测手段。</p><p>没有这层抽象，超时会偷偷写进安全证明，FLP 的异步前提就被偷换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检测器把不可靠怀疑做成带完备/准确档的预言机。</li><li>\\(\\Diamond\\mathcal{S}\\) 已够崩溃共识；\\(\\mathcal{P}\\) 在真实网络不可得。</li><li>心跳实现依赖部分同步；安全仍按异步证。</li><li>出处：Chandra and Toueg, JACM 1996；Chandra, Hadzilacos and Toueg。</li></ul>',10))])}const S=l(p,[["render",m]]);export{P as __pageData,S as default};
